  builder_.add_TARGET_HEIGHT_M(TARGET_HEIGHT_M);
  builder_.add_TX_SURFACE_HEIGHT_M(TX_SURFACE_HEIGHT_M);
  builder_.add_TX_ABSOLUTE_HEIGHT_M(TX_ABSOLUTE_HEIGHT_M);
