  builder_.add_REFLECTION_CONTRIBUTION_DB(REFLECTION_CONTRIBUTION_DB);
  builder_.add_DIFFRACTION_PARAMETER(DIFFRACTION_PARAMETER);
  builder_.add_LINK_MARGIN_DB(LINK_MARGIN_DB);
  builder_.add_EXCESS_LOSS_DB(EXCESS_LOSS_DB);
  builder_.add_PATH_LOSS_DB(PATH_LOSS_DB);
  builder_.add_PATH_CLASS(PATH_CLASS);
  builder_.add_POSITIVE_LINK_MASK(POSITIVE_LINK_MASK);
  builder_.add_OCCLUDED_MASK(OCCLUDED_MASK);
  builder_.add_VISIBLE_MASK(VISIBLE_MASK);
  builder_.add_GRID_HEIGHT(GRID_HEIGHT);
  builder_.add_GRID_WIDTH(GRID_WIDTH);
